function loop() {
  if (gameOver) return;
  // Fade previous frame for motion blur effect
  ctx.fillStyle = 'rgba(0,0,10,0.2)';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // Draw starfield background
  drawStars();
  // Draw neon gradient background
  const bgGrad = ctx.createLinearGradient(0,0,0,canvas.height);
  bgGrad.addColorStop(0,"#001");
  bgGrad.addColorStop(1,"#004");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // Draw moving neon grid
  drawGrid();
  player.update();
  // Draw afterimage trail
  drawPlayerTrail();
  player.draw();
  updateObstacles();
  drawObstacles();
  if (checkCollision()) { gameOver = true; alert('Game Over! Score: ' + Math.floor(score)); return; }
  score += 0.1;
  ctx.fillStyle = '#fff';
  ctx.font = '16px monospace';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
  time++;
  requestAnimationFrame(loop);
}

